import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { live, useClaims } from '../claims/claims';
import { floorOf, useSettings } from '../settings/settings';
import { lateOf } from '../overdue/overdue';
import { personDue, personExcess, trimmedTotal, useRates } from './rates';

// A person's due-total (the sum of their counting claims' rounded figures, at most the sheet's cap), their
// excess over the cap, and the sheet's due-total (everyone's, skipping n/a, trimmed).
function DueHead() {
  return <th>Due total</th>;
}

function PersonDue({ person }: { person: Person }) {
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const mine = live((claims.data ?? []).filter((c) => c.personId === person.id), [person]);
  return <td data-testid="person-due-total">{personDue(mine, rates.data, person.grades, today, floor, lateOf(settings, today, [person]), settings?.cap)}</td>;
}

function ExcessHead() {
  return <th>Excess</th>;
}

function PersonExcess({ person }: { person: Person }) {
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const mine = live((claims.data ?? []).filter((c) => c.personId === person.id), [person]);
  return (
    <td data-testid="person-excess">
      {personExcess(mine, rates.data, person.grades, today, floorOf(settings), lateOf(settings, today, [person]), settings?.cap)}
    </td>
  );
}

/** The sheet's due-total (the current sheet's unless another is named): everyone's (retired people included)
 *  due-totals added up, skipping n/a, trimmed of the single highest and lowest when three or more people have one. */
export function useSheetDueTotal(of?: string): string {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const dues = (people.data ?? []).map((p) =>
    personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floor, lateOf(settings, today, [p]), settings?.cap),
  );
  return trimmedTotal(dues);
}

function DueTotal() {
  return (
    <p>
      Due total <strong data-testid="rollup-due-total">{useSheetDueTotal()}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 15, Component: DueHead }),
  PersonColumns.fill({ order: 15, Component: PersonDue }),
  PersonColumnHeads.fill({ order: 15.5, Component: ExcessHead }),
  PersonColumns.fill({ order: 15.5, Component: PersonExcess }),
  HomeMain.fill({ order: 35, Component: DueTotal }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { counts, live, useClaims } from '../claims/claims';
import { floorOf, useSettings } from '../settings/settings';
import { trimmedTotal, useRates } from '../rates/rates';
import { lateOf, overdueFigures } from './overdue';

// A person's overdue count and overdue-total (the due of their overdue claims that count), and the sheet's.
function OverdueHead() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

function useOverdue(of?: string) {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  return (person: Person) =>
    overdueFigures(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]).filter(counts),
      rates.data,
      person.grades,
      floorOf(settings),
      today,
      lateOf(settings, today, [person]),
    );
}

function PersonOverdue({ person }: { person: Person }) {
  const { count, total } = useOverdue()(person);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{total}</td>
    </>
  );
}

/** The sheet's overdue figures (the current sheet's unless another is named): everyone's overdue counts
 *  added up, and their overdue-totals added up trimmed of the single highest and lowest when three or more
 *  people have one. */
export function useSheetOverdue(of?: string): { count: number; total: string } {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useOverdue(sheet));
  return { count: figures.reduce((n, f) => n + f.count, 0), total: trimmedTotal(figures.map((f) => f.total)) };
}

function OverdueTotal() {
  const { count, total } = useSheetOverdue();
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 17, Component: OverdueHead }),
  PersonColumns.fill({ order: 17, Component: PersonOverdue }),
  HomeMain.fill({ order: 36, Component: OverdueTotal }),
];
import { useMutationState, useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** `version` moves on with each stored edit; an edit is saved only over the version its editor loaded.
 *  `statementCount` is how many statements were taken of them; `statedTotal` (two decimals, or n/a)
 *  and `statementDate` (yyyy-MM-dd) are the last one's, null when none was taken. `retired` is set
 *  as soon as a `retiredFrom` date (yyyy-MM-dd, null when not retired) is, whatever the date;
 *  `retiredNow` once the sheet's today reaches it: from then their OPEN claims count in no live total
 *  unless a statement bound them, as a hold's would.
 *  `holds` are their holds, oldest first; `held` whether they have any. Their OPEN claims dated within
 *  a hold count in no live total unless a statement bound them; their SETTLED ones still do.
 *  `patronIds` are the ids of the other people on the sheet they named as their patrons, in the order they named them.
 *  `grade` is the grade in force on the sheet's today; `grades` every grade with the date it applies from.
 *  `terms` are their own terms in whole days (null when none), ahead of their grade's and the sheet's.
 *  `contact` is their contact (trimmed, lower-cased; null when none), no other person's on the sheet.
 *  `aliases` are other names they are found by (no name or other alias on the sheet), sorted as names are compared.
 *  `clashing` whether their name or an alias is used as a name or alias on another sheet of the sheet's tree (its
 *  ancestors and descendants); every edit of them is refused until it renames them to a name that does not clash.
 *  `origin` is the id of the sheet they were transferred from (null when they were not).
 *  `pastRetirements` are the retirements they were unretired from, oldest first. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  retiredNow: boolean;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  pastRetirements: PastRetirement[];
};

/** A past retirement: from the date retired from to the day unretired (yyyy-MM-dd). No claim dated
 *  after its from-date and before its to-date may be added. */
export type PastRetirement = { from: string; to: string };

/** A hold from its from-date to its to-date (yyyy-MM-dd, both inclusive; null for no end). */
export type Hold = { from: string; to: string | null };

/** Whether the hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => h.from <= date && (h.to === null || date <= h.to);

export const GRADES = ['A', 'B', 'C'] as const;

/** A person's grades, each with the date (yyyy-MM-dd) it applies from; the first has none (null),
 *  applying from the beginning of time. */
export type Grades = { grade: string; from: string | null }[];

/** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(grades: Grades, on: string | undefined): string {
  let best = grades[0];
  for (const g of grades) {
    if (g.from === null || (on !== undefined && g.from <= on)) {
      if ((best.from ?? '') <= (g.from ?? '')) best = g;
    }
  }
  return best?.grade ?? 'A';
}

/** Under the sheet's key, so loading the sheet again re-reads its people. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

export function usePeople(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(peopleKey(sheet), asOf),
    queryFn: () => getJson<Person[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, asOf)),
    enabled: sheet !== '',
  });
}

/** The id of the person whose editor is open in the person form ('' when it adds). */
export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether the people list shows retired people too; off when the screen is first opened. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

/** The mutation key of an action on a person's row (a statement, a hold, a retirement): the row
 *  shows only the error of the latest one taken, so taking the next action clears an earlier one's. */
export const personActionKey = (sheet: string, personId: number) => [...peopleKey(sheet), personId, 'action'] as const;

/** When the latest action on the person's row was taken (0 when none was). */
export function useLatestPersonAction(sheet: string, personId: number): number {
  const taken = useMutationState({
    filters: { mutationKey: personActionKey(sheet, personId) },
    select: (m) => m.state.submittedAt,
  });
  return Math.max(0, ...taken);
}

/** The ids of the people selected for a bulk grade, kept in the URL (`selectedPeople`, comma separated). */
export function useSelectedPeople(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedPeople', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
}

